import { type Money, DoubleElevenPromotion } from "./types.ts";

export const doubleElevenPromotion: DoubleElevenPromotion = {
  threshold: 300,
  discount: 50,
};

export function applyDoubleElevenDiscount(total: Money): Money {
  if (total < 0) return 0;
  if (total < doubleElevenPromotion.threshold) return total;
  return total - doubleElevenPromotion.discount;
}
```

